import { constants, lstatSync, realpathSync } from "node:fs";
import { isAbsolute, relative, resolve, sep } from "node:path";

export type WorkspaceExternalWriteSource =
  | "trusted-system"
  | "direct-operator"
  | "external"
  | "derived"
  | "invalid"
  | "missing";

export type WorkspaceExternalWriteProvenance = {
  source: WorkspaceExternalWriteSource;
};

export type WorkspaceExternalWritePolicyOptions = {
  workspaceRoot: string;
};

export type WorkspaceExternalWritePolicyErrorCode =
  | "WORKSPACE_EXTERNAL_WRITE_SOURCE_DENIED"
  | "WORKSPACE_EXTERNAL_WRITE_PATH_ESCAPE"
  | "WORKSPACE_EXTERNAL_WRITE_RESIDUAL_NAMESPACE";

export class WorkspaceExternalWritePolicyError extends Error {
  readonly code: WorkspaceExternalWritePolicyErrorCode;

  constructor(code: WorkspaceExternalWritePolicyErrorCode, message: string) {
    super(message);
    this.name = "WorkspaceExternalWritePolicyError";
    this.code = code;
  }
}

const TRUSTED_SOURCES = new Set<WorkspaceExternalWriteSource>([
  "trusted-system",
  "direct-operator",
]);

function normalizeSource(
  source: WorkspaceExternalWriteSource | WorkspaceExternalWriteProvenance,
): WorkspaceExternalWriteSource {
  return typeof source === "string" ? source : source.source;
}

export function isTrustedWorkspaceExternalWriteSource(
  source: WorkspaceExternalWriteSource | WorkspaceExternalWriteProvenance,
): boolean {
  return TRUSTED_SOURCES.has(normalizeSource(source));
}

export function classifyWorkspaceExternalWriteSource(
  source: WorkspaceExternalWriteSource | WorkspaceExternalWriteProvenance,
): "trusted" | "untrusted" {
  return isTrustedWorkspaceExternalWriteSource(source) ? "trusted" : "untrusted";
}

function isWithin(root: string, candidate: string): boolean {
  const rel = relative(root, candidate);
  return rel === "" || (!rel.startsWith(`..${sep}`) && rel !== ".." && !isAbsolute(rel));
}

function canonicalExistingPath(path: string): string {
  try {
    return realpathSync.native(path);
  } catch {
    const parent = resolve(path, "..");
    return resolve(parent, path.slice(parent.length + 1));
  }
}

function canonicalWorkspaceRoot(workspaceRoot: string): string {
  try {
    return realpathSync.native(resolve(workspaceRoot));
  } catch {
    return resolve(workspaceRoot);
  }
}

function hasResidualNamespace(path: string): boolean {
  if (process.platform !== "win32") {
    return false;
  }
  return path.startsWith("\\\\?\\") || path.startsWith("\\\\.\\") || /^\\\\/.test(path);
}

/**
 * Validates the single workspace-external write boundary used by write, edit,
 * and apply_patch callers. This function deliberately performs no write.
 */
export function assertWorkspaceExternalWriteAllowed(
  source: WorkspaceExternalWriteSource | WorkspaceExternalWriteProvenance,
  targetPath: string,
  options: WorkspaceExternalWritePolicyOptions,
): void {
  if (hasResidualNamespace(targetPath)) {
    throw new WorkspaceExternalWritePolicyError(
      "WORKSPACE_EXTERNAL_WRITE_RESIDUAL_NAMESPACE",
      `Residual Windows namespace path cannot be validated deterministically: ${targetPath}`,
    );
  }

  const workspaceRoot = canonicalWorkspaceRoot(options.workspaceRoot);
  const lexicalTarget = resolve(targetPath);
  const canonicalTarget = canonicalExistingPath(lexicalTarget);
  const targetIsOutsideWorkspace = !isWithin(workspaceRoot, lexicalTarget) || !isWithin(workspaceRoot, canonicalTarget);

  if (!targetIsOutsideWorkspace) {
    return;
  }

  if (!isTrustedWorkspaceExternalWriteSource(source)) {
    throw new WorkspaceExternalWritePolicyError(
      "WORKSPACE_EXTERNAL_WRITE_SOURCE_DENIED",
      `Workspace-external write denied for source ${normalizeSource(source)}`,
    );
  }
}

export function validateWorkspaceExternalWrite(
  source: WorkspaceExternalWriteSource | WorkspaceExternalWriteProvenance,
  targetPath: string,
  options: WorkspaceExternalWritePolicyOptions,
): void {
  assertWorkspaceExternalWriteAllowed(source, targetPath, options);
}

export function assertExternalWriteAllowed(
  source: WorkspaceExternalWriteSource | WorkspaceExternalWriteProvenance,
  targetPath: string,
  options: WorkspaceExternalWritePolicyOptions,
): void {
  assertWorkspaceExternalWriteAllowed(source, targetPath, options);
}

export function assertWorkspaceExternalWriteProvenance(
  source: WorkspaceExternalWriteSource | WorkspaceExternalWriteProvenance,
  targetPath: string,
  options: WorkspaceExternalWritePolicyOptions,
): void {
  assertWorkspaceExternalWriteAllowed(source, targetPath, options);
}

